parameters.jsCode:
const platform = $('Normalize Input').first().json.platform;
const media = $('Normalize Input').first().json.mediaAssets || [];
const specs = { linkedin: { name: 'LinkedIn', max: 300 }, facebook: { name: 'Facebook', max: 200 }, instagram: { name: 'Instagram', max: 150 }, threads: { name: 'Threads', max: 100 }, devto: { name: 'Dev.to', max: 1200, hint: 'Write a concise DEV article in Markdown with a clear title, short intro, useful sections, and a practical takeaway.' }, youtube: { name: 'YouTube Community', max: 280, hint: 'Community tab text only. Never video uploads, Shorts, or studio publishing.' }, producthunt: { name: 'Product Hunt', max: 260 } };
const spec = specs[platform] || specs.linkedin;
const base = $('Normalize Input').first().json.optimizedPrompt || $('Normalize Input').first().json.userPrompt;
const systemExtra = spec.hint ? ` ${spec.hint}` : '';
const mediaNote = media.length ? ` User attached ${media.length} image(s); write caption/copy that complements the visual.` : '';
return [{ json: { platform, platformName: spec.name, systemPrompt: `Expert ${spec.name} creator.${systemExtra}${mediaNote}`, userMessage: `${base}\n\nOutput ONLY paste-ready ${platform === 'devto' ? 'Markdown article content' : 'post text'}.` } }];

const input = $('Normalize Input').first().json;
const content = $('Generate Platform Post').first().json.text || '';
const summary = $('Article Summarizer').first().json.text || '';
const platform = input.platform;
const media = input.mediaAssets || [];
const tokens = input.platformTokens || {};
const token = tokens[platform];

function devToTitle(markdown) {
  const line = markdown.split('\n').map((value) => value.replace(/^#+\s*/, '').trim()).find(Boolean) || 'SocialFlow AI post';
  return line.replace(/[.!?:;,-]+$/, '').slice(0, 90) || 'SocialFlow AI post';
}

function devToBody(markdown, sourceUrl, summaryText) {
  const hasHeading = /^#{1,3}\s+/m.test(markdown);
  const intro = sourceUrl ? `Source: ${sourceUrl}\n\n` : '';
  const fallback = summaryText ? `${markdown}\n\n## Context\n\n${summaryText}` : markdown;
  return `${intro}${hasHeading ? markdown : fallback}`.trim();
}

let publishResult = { success: false, skipped: true };

if (input.publish && token?.accessToken && content) {
  try {
    if (platform === 'linkedin') {
      const personRes = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.linkedin.com/v2/userinfo', headers: { Authorization: `Bearer ${token.accessToken}` } });
      const author = `urn:li:person:${personRes.sub}`;
      const hasMedia = media.length > 0;
      await this.helpers.httpRequest({ method: 'POST', url: 'https://api.linkedin.com/v2/ugcPosts', headers: { Authorization: `Bearer ${token.accessToken}`, 'Content-Type': 'application/json', 'X-Restli-Protocol-Version': '2.0.0' }, body: { author, lifecycleState: 'PUBLISHED', specificContent: { 'com.linkedin.ugc.ShareContent': { shareCommentary: { text: content }, shareMediaCategory: hasMedia ? 'IMAGE' : 'NONE' } }, visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' } } });
      publishResult = { success: true, platform: 'linkedin', mediaAttached: hasMedia, mediaCount: media.length };
    } else if (platform === 'devto') {
      const article = await this.helpers.httpRequest({ method: 'POST', url: 'https://dev.to/api/articles', headers: { 'api-key': token.accessToken, 'Content-Type': 'application/json', Accept: 'application/json', 'User-Agent': 'SocialFlowAI' }, body: { article: { title: devToTitle(content), body_markdown: devToBody(content, input.websiteUrl, summary), published: true, tags: 'ai,productivity,socialflow' } }, json: true });
      publishResult = { success: true, platform: 'devto', postId: article.id ? String(article.id) : undefined, url: article.url, mediaCount: media.length };
    } else if (platform === 'youtube') {
      publishResult = { success: false, error: 'YouTube Community auto-publish is coming soon (text/image posts only — not video uploads).', mediaCount: media.length };
    } else {
      publishResult = { success: false, error: `Auto-publish not yet implemented for ${platform}. Content generated successfully.`, mediaCount: media.length };
    }
  } catch (e) {
    publishResult = { success: false, error: e.message };
  }
} else if (input.publish && !token) {
  publishResult = { success: false, error: 'No token provided for platform' };
}

const wordCount = content.split(/\s+/).filter(Boolean).length;
return [{ json: { success: true, executionId: input.executionId, userId: input.userId, platform, content, summary, wordCount, qualityScore: Math.min(100, wordCount * 2), publishResult, mediaAssets: media, generatedAt: new Date().toISOString() } }];

